replacements.old:
if (Level.TimeSeconds < NextVersusClientCastTime || IsVersusSpellLocked())
    return;

NextVersusClientCastTime = Level.TimeSeconds
    + GetVersusSpellCooldown(SelectedVersusSpell);
AimRot = GetVersusAimRotation();

if (Level.TimeSeconds < NextVersusServerCastTime)
{
    Log("HPVersusCastReject reason=cooldown pawn=" $ string(self)
        $ " slot=" $ string(VersusSlot));
    return;
}

if (bVersusDead || Health <= 0)

NextVersusServerCastTime = Level.TimeSeconds
    + GetVersusSpellCooldown(SelectedVersusSpell);
VersusCooldownEndTime = NextVersusServerCastTime;
Charge = FClamp(Charge, 0.0, 1.0);

replacements.new:
// No fire cooldown. Keep the replicated HUD field clear even if an
// older prepared pawn retained a server-time deadline.
VersusCooldownEndTime = 0.0;
Charge = FClamp(Charge, 0.0, 1.0);

local byte CastSerialBefore;
local byte CastSerialFirst;
local HPVersusPRI ProbeAPRI;

replacements.old:
A.NextVersusServerCastTime = 0.0;
A.ServerRequestCast(1.0, A.Rotation, A.GetVersusFallbackMuzzle(A.Rotation));
RemainingCooldown = A.NextVersusServerCastTime - Level.TimeSeconds;
VersusProbeResult(RemainingCooldown > 0.60 && RemainingCooldown < 0.80,
    "per-spell-server-cooldown");

replacements.new:
// A stale deadline from an older build must never suppress fire.
A.NextVersusServerCastTime = Level.TimeSeconds + 1400.0;
A.VersusCooldownEndTime = A.NextVersusServerCastTime;
CastSerialBefore = A.VersusCastSerial;
A.ServerRequestCast(1.0, A.Rotation, A.GetVersusFallbackMuzzle(A.Rotation));
CastSerialFirst = A.VersusCastSerial;
A.ServerRequestCast(1.0, A.Rotation, A.GetVersusFallbackMuzzle(A.Rotation));
VersusProbeResult(CastSerialFirst != CastSerialBefore
    && A.VersusCastSerial != CastSerialFirst
    && A.VersusCooldownEndTime == 0.0,
    "repeat-cast-without-cooldown");
